    priority_timeframe: priorityTimeframe,
    priority_call: priorityCall,
    factor_breakdown: factorBreakdown,
    key_factors: buildKeyFactors(factorBreakdown),
    warnings,
    reasoning_summary: row.reasoning_summary || output.reasoning_summary || "",
    score_bullish: toNumber(row.score_bullish != null ? row.score_bullish : output.score_bullish != null ? output.score_bullish : null),
    score_bearish: toNumber(row.score_bearish != null ? row.score_bearish : output.score_bearish != null ? output.score_bearish : null),
    score_neutral: toNumber(row.score_neutral != null ? row.score_neutral : output.score_neutral != null ? output.score_neutral : null),
    non_neutral_count: toNumber(output.non_neutral_count != null ? output.non_neutral_count : null),
    logic_document: row.logic_document || output.logic_document || null,
    logic_document_version: row.logic_document_version || output.logic_document_version || null,
    conviction_model: convictionModel,
    timeframe_models: output.timeframe_models || {},
    display_metrics: {
      bull_case: convictionModel.bullish_argument_pct,
      bear_case: convictionModel.bearish_argument_pct,
      winning_side: convictionModel.winning_side,
      conviction: convictionModel.final_conviction,
      net_edge: convictionModel.net_edge_pct,
      directional_participation: convictionModel.directional_participation_pct,
      neutral: convictionModel.neutral_evidence_pct != null ? convictionModel.neutral_evidence_pct : convictionModel.neutral_pct,
      verdict_strength: convictionModel.verdict_strength,
      bull_case_weight: convictionModel.bull_case_weight != null ? convictionModel.bull_case_weight : null,
      bear_case_weight: convictionModel.bear_case_weight != null ? convictionModel.bear_case_weight : null
    },
    full_output: output
  };
}

