        neutral_evidence_pct: null,
        directional_participation_pct: null,
        active_participation_pct: null,
        net_edge_pct: null,
        final_conviction: null,
        verdict_strength: "MARKET_CLOSED",
        winning_side: "MARKET_CLOSED",
        final_conviction_logic: "24H priority timeframe is closed by weekend rule.",
        bull_case_weight: null,
        bear_case_weight: null,
        neutral_weight: null
      }
    : normaliseConvictionModel(output, priorityTimeframe);

  return {
    agent,
    status: "live",
    market_status: isMarketOpen(agent) ? "open" : "closed",
    last_run_et: row.run_time_et || row.created_at || null,
    generated_at: row.run_time_et || row.created_at || null,
    sealed_at: row.created_at || output.created_at || row.run_time_et || null,
    valid_from: row.valid_from || output.valid_from || row.created_at || output.created_at || row.run_time_et || null,
    source_run_id: row.source_run_id || output.source_run_id || output.execution_id || output.workflow_execution_id || null,
    refresh_request_id: row.refresh_request_id || row.request_id || output.refresh_request_id || output.request_id || null,
    summary: agent + " Layer 1 raw call generated from sealed independent workflow.",
    calls,
    priority_timeframe: priorityTimeframe,
    priority_call: priorityCall,
    factor_breakdown: factorBreakdown,
    key_factors: buildKeyFactors(factorBreakdown),
    warnings,
    reasoning_summary: row.reasoning_summary || output.reasoning_summary || "",
    score_bullish: toNumber(row.score_bullish != null ? row.score_bullish : output.score_bullish != null ? output.score_bullish : null),
    score_bearish: toNumber(row.score_bearish != null ? row.score_bearish : output.score_bearish != null ? output.score_bearish : null),
    score_neutral: toNumber(row.score_neutral != null ? row.score_neutral : output.score_neutral != null ? output.score_neutral : null),
    non_neutral_count: toNumber(output.non_neutral_count != null ? output.non_neutral_count : null),
    logic_document: row.logic_document || output.logic_document || null,
    logic_document_version: row.logic_document_version || output.logic_document_version || null,
    conviction_model: convictionModel,
    timeframe_models: output.timeframe_models || {},
    display_metrics: {
      bull_case: convictionModel.bullish_argument_pct,
      bear_case: convictionModel.bearish_argument_pct,
      winning_side: convictionModel.winning_side,
      conviction: convictionModel.final_conviction,
      net_edge: convictionModel.net_edge_pct,
      directional_participation: convictionModel.directional_participation_pct,
      neutral: convictionModel.neutral_evidence_pct != null ? convictionModel.neutral_evidence_pct : convictionModel.neutral_pct,
      verdict_strength: convictionModel.verdict_strength,
      bull_case_weight: convictionModel.bull_case_weight != null ? convictionModel.bull_case_weight : null,
      bear_case_weight: convictionModel.bear_case_weight != null ? convictionModel.bear_case_weight : null
    },
    full_output: output
  };
}

const selectedRows = selectLatestRowsByAgent();
const provenance = buildSelectionProvenance(selectedRows);
const rowByAgent = Object.fromEntries(selectedRows.map((row) => [row.agent_name, row]));

const dashboard = {
  source_run_id: provenance.sourceRunId,
  refresh_request_id: provenance.refreshRequestId,
  dashboard_meta: {
    system_timezone: "America/New_York",
    execution_clock: "07:00 ET primary run",
    last_updated_et: new Date().toISOString(),
    architecture: "Layer 1 agents are sealed independent raw signal producers. No cross-agent communication.",
    weekend_rule: "BTC remains open on weekends. USD, EUR, GOLD and NQ do not issue 24h calls on Saturday or Sunday.",
    london_weekday: londonWeekday,
    required_agents: agents,
    source_run_id_consistency: provenance.sourceRunConsistency,
    refresh_request_id_consistency: provenance.refreshRequestConsistency,
    publication_consistency: provenance.consistencyStatus,
    source_run_ids: provenance.sourceRunIds,
    refresh_request_ids: provenance.refreshRequestIds
  },
  agents: agents.map((agent) => fromRow(agent, rowByAgent[agent]))
};

return [{
  json: {
    file_content: JSON.stringify(dashboard, null, 2),
    dashboard
  }
}];
